from pathlib import Path

def terminal_result(destination: Path | None) -> str | None:
    return None if destination is None else str(destination)

def status_text(result: str | None) -> str:
    return "Cancelled" if result is None else "Exported: " + result

def should_retry(result: str | None) -> bool:
    return result is None
